SELECT p.id AS position_id, w.id AS wallet_trade_id, w.side, w.execution_reason, w.decision_price_usdt, w.price_usdt, w.execution_price_observed_at, w.executed_at, LEFT(w.execution_message,2000) AS msg FROM paper_position p JOIN wallet_trade w ON w.symbol=p.symbol AND w.executed_at BETWEEN p.opened_at - INTERVAL 10 SECOND AND p.closed_at + INTERVAL 10 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, w.executed_at LIMIT 40;
SELECT o.id, o.symbol, o.status, o.started_at, o.last_evidence_at, o.latest_signal_id, o.evidence_count, o.buy_count, o.watch_count, o.neutral_count, o.bearish_count, o.evidence_score, o.opportunity_health, o.five_minute_decision, o.one_hour_decision, o.execution_source, o.recommended_position_percent, o.decision_code, LEFT(o.decision_explanation,1200) AS expl, o.executed_at FROM execution_opportunity o JOIN paper_position p ON p.symbol=o.symbol AND o.executed_at BETWEEN p.opened_at - INTERVAL 10 SECOND AND p.opened_at + INTERVAL 5 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY o.executed_at LIMIT 20